import type React from "react";
import { tv } from "tailwind-variants";

export const segmentedControl = tv({
  base: "bg-muted inline-flex items-center justify-start rounded-md p-1",
  defaultVariants: {
    size: "md",
  },
  variants: {
    size: {
      lg: "h-12",
      md: "h-10",
      sm: "h-8",
    },
  },
});
export const segmentedItem = tv({
  base: "ring-offset-background focus-visible:ring-ring hover:bg-background/50 inline-flex cursor-pointer items-center justify-center rounded-sm whitespace-nowrap transition-colors duration-150 focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50 motion-reduce:transition-none",
  defaultVariants: {
    active: false,
    size: "md",
  },
  variants: {
    active: {
      false: "",
      true: "bg-background text-foreground hover:bg-background shadow-sm",
    },
    size: {
      lg: "px-4 py-2 text-base",
      md: "px-3 py-1.5 text-sm",
      sm: "px-2 py-1 text-xs",
    },
  },
});
export const iconSize = {
  lg: "h-5 w-5",
  md: "h-4 w-4",
  sm: "h-3 w-3",
};
export const handleSegmentKey = (
  event: React.KeyboardEvent<HTMLButtonElement>
) => {
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) {
    return;
  }
  const parent = event.currentTarget.closest('[role="tablist"]');
  if (!parent) {
    return;
  }
  const buttons = [
    ...parent.querySelectorAll<HTMLButtonElement>(
      'button[role="tab"]:not(:disabled)'
    ),
  ];
  const index = buttons.indexOf(event.currentTarget);
  const direction = getComputedStyle(parent).direction === "rtl" ? -1 : 1;
  let nextIndex =
    (index +
      (event.key === "ArrowRight" ? direction : -direction) +
      buttons.length) %
    buttons.length;
  if (event.key === "Home") {
    nextIndex = 0;
  }
  if (event.key === "End") {
    nextIndex = buttons.length - 1;
  }
  event.preventDefault();
  buttons[nextIndex]?.focus();
  buttons[nextIndex]?.click();
};

"use client";

import type { LucideIcon } from "lucide-react";
import React from "react";
import type { VariantProps } from "tailwind-variants";

import type { SelectOption } from "@/lib/types";
import { cn } from "@/lib/utils";
import { ConditionalTooltip } from "@/registry/new-york/conditional-tooltip/ConditionalTooltip";
import { useKitzeUI } from "@/registry/new-york/kitze-ui-context/KitzeUIContext";
import {
  segmentedControl,
  segmentedItem,
  iconSize,
  handleSegmentKey,
} from "@/registry/new-york/segmented-control/SegmentedControlStyles";
import type { SelectMobileViewType } from "@/registry/new-york/simple-select/SimpleSelect";
import { SimpleSelect } from "@/registry/new-york/simple-select/SimpleSelect";

export type SegmentedControlMobileViewType = "keep" | SelectMobileViewType;
export interface SegmentedControlOption {
  value: string;
  label: string;
  icon?: LucideIcon | undefined;
  tooltip?: string | undefined;
  leftIcon?: LucideIcon | undefined;
  rightIcon?: LucideIcon | undefined;
  leftSide?: React.ComponentType | undefined;
  rightSide?: React.ComponentType | undefined;
  disabled?: boolean | undefined;
}
export interface SegmentedControlProps extends VariantProps<
  typeof segmentedControl
> {
  options: SegmentedControlOption[];
  /** Hide visible labels on options with icons; labels remain accessible. */
  iconOnly?: boolean | undefined;
  value: string;
  onChange: (value: string) => void;
  className?: string | undefined;
  tabClassName?: string | undefined;
  activeTabClassName?: string | undefined;
  mobileView?: SegmentedControlMobileViewType | undefined;
  mobileViewSearch?: boolean | undefined;
  drawerTitle?: string | undefined;
  placeholder?: string | undefined;
  disabled?: boolean | undefined;
}
export const SegmentedControl = ({
  options,
  iconOnly = false,
  value,
  onChange,
  className,
  tabClassName,
  activeTabClassName,
  size = "md",
  mobileView = "keep",
  mobileViewSearch = false,
  drawerTitle = "Select an option",
  placeholder = "Select an option",
  disabled,
}: SegmentedControlProps) => {
  const { isMobile } = useKitzeUI();

  if (isMobile && mobileView !== "keep") {
    const selectOptions: SelectOption[] = options.map((option) => ({
      disabled: disabled || option.disabled,
      icon: option.icon ?? option.leftIcon,
      label: option.label,
      value: option.value,
    }));
    return (
      <SimpleSelect
        options={selectOptions}
        value={value}
        onValueChange={onChange}
        placeholder={placeholder}
        className={className}
        mobileView={mobileView}
        mobileViewSearch={mobileViewSearch}
        drawerTitle={drawerTitle}
        disabled={disabled}
      />
    );
  }

  return (
    <div
      className={segmentedControl({
        className,
        size,
      })}
      role="tablist"
      aria-orientation="horizontal"
    >
      {options.map((option) => {
        const isActive = option.value === value;
        const LeftIcon = option.icon ?? option.leftIcon;
        const RightIcon = option.rightIcon;
        const LeftSide = option.leftSide;
        const RightSide = option.rightSide;
        const hideLabel = iconOnly && Boolean(LeftIcon || RightIcon);
        return (
          <ConditionalTooltip
            key={option.value}
            condition={Boolean(option.tooltip)}
            content={option.tooltip}
          >
            <button
              type="button"
              role="tab"
              tabIndex={isActive ? 0 : -1}
              onKeyDown={handleSegmentKey}
              onClick={() =>
                !disabled && !option.disabled && onChange(option.value)
              }
              className={cn(
                segmentedItem({
                  active: isActive,
                  size,
                }),
                "gap-2",
                hideLabel && "aspect-square px-2",
                tabClassName,
                isActive && activeTabClassName
              )}
              aria-label={hideLabel ? option.label : undefined}
              aria-selected={isActive}
              disabled={disabled || option.disabled}
            >
              {LeftSide && <LeftSide />}
              {LeftIcon && (
                <LeftIcon
                  aria-hidden="true"
                  className={iconSize[size || "md"]}
                />
              )}
              <span className={hideLabel ? "sr-only" : undefined}>
                {option.label}
              </span>
              {RightIcon && (
                <RightIcon
                  aria-hidden="true"
                  className={iconSize[size || "md"]}
                />
              )}
              {RightSide && <RightSide />}
            </button>
          </ConditionalTooltip>
        );
      })}
    </div>
  );
};

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
